examples.setup:
data class Invoice(val id: String, val customer: String, val status: String, val issued: String, val owner: String, val amount: Int)
val invoices = listOf(
    Invoice("INV-1042", "Northfield Traders", "Paid", "2026-09-02", "Ana", 1240),
    Invoice("INV-1043", "Cobalt Ltd", "Due", "2026-09-11", "Ben", 860),
    Invoice("INV-1044", "Fernway Inc", "Overdue", "2026-08-21", "Chen", 4300),
    Invoice("INV-1045", "Tidewater Toys", "Due", "2026-09-18", "Ana", 395),
    Invoice("INV-1046", "Westbridge Imports", "Paid", "2026-09-20", "Dev", 2150),
    Invoice("INV-1047", "Lumen", "Due", "2026-09-24", "Ben", 1720),
)
val columns = listOf<MonarchDataTableColumn<Invoice>>(
    MonarchDataTableColumn("Customer", id = "customer", hideable = false) { it.customer },
    MonarchDataTableColumn(
        "Status",
        id = "status",
        tone = {
            when (it.status) {
                "Paid" -> MonarchTone.Success
                "Overdue" -> MonarchTone.Danger
                else -> MonarchTone.Neutral
            }
        },
    ) { it.status },
    MonarchDataTableColumn("Issued", id = "issued") { it.issued },
    MonarchDataTableColumn("Owner", id = "owner") { it.owner },
    MonarchDataTableColumn("Amount", id = "amount", numeric = true, comparator = compareBy<Invoice> { it.amount }) { "$" + "%,d".format(it.amount) },
)
var sort by remember { mutableStateOf<MonarchDataTableSort?>(MonarchDataTableSort("issued", MonarchDataTableSortDirection.Descending)) }
var selected by remember { mutableStateOf(setOf("INV-1044")) }
